    for match in re_ansi.finditer(ansi_text):
        start, end = match.span(0)
        osc, sgr = match.groups()
        if start > position:
            yield (ansi_text[position:start],)
        if sgr:
            if sgr == '(':
                position = end + 1
                continue
            if sgr.endswith('m'):
                yield ('', sgr[1:-1])
        else:
            yield ('', None, osc)
        position = end
    if position < len(ansi_text):
        yield (ansi_text[position:],)

